CREATE OR REPLACE FUNCTION public.claim_community_message(_context text,_reference_id uuid) RETURNS boolean LANGUAGE plpgsql SET search_path=public AS $$ DECLARE claimed boolean; BEGIN IF _context NOT IN ('community_plan','community_premium','community_meeting_invitation','community_request','community_response','lp_activation','lp_admin_notice','lp_rd_conversion','public_profile_host_notice') THEN RETURN false; END IF; INSERT INTO public.community_message_claims(context,reference_id) VALUES(_context,_reference_id) ON CONFLICT(context,reference_id) DO UPDATE SET state='sending',claimed_at=now(),updated_at=now() WHERE community_message_claims.state='failed' OR (community_message_claims.state='sending' AND community_message_claims.claimed_at<now()-interval '10 minutes') RETURNING true INTO claimed; RETURN coalesce(claimed,false); END $$;